@Service
public class OrderService {

    @Autowired
    private OrderRepository orderRepository;

    // The public entry point
    public void processOrder(Order order) {
        // BUG: Self-invocation! 'this.validateAndSave' bypasses the Spring proxy.
        // The @Transactional annotation on validateAndSave will be completely ignored.
        this.validateAndSave(order);
    }

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void validateAndSave(Order order) {
        orderRepository.save(order);
        // If an exception occurs here, no new transaction was actually created,
        // and rollback behavior will not match expectations of REQUIRES_NEW.
    }
}
